Sdb* process_elf_version_info(ELFOBJ* bin, Elf_Shdr* shdr, int sz) {
    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    if (!shdr || shdr->sh_size == 0 || sz <= 0) {
        sdb_free(sdb);
        return NULL;
    }

    // Assuming the presence of a helper function elf_get_section_name to retrieve section names
    char* section_name = elf_get_section_name(bin, shdr);
    if (!section_name) {
        sdb_free(sdb);
        return NULL;
    }

    // Assuming a function elf_get_version_data to parse version definitions
    VersionDefinition* version_data = elf_get_version_data(bin, shdr);
    if (!version_data) {
        free(section_name);
        sdb_free(sdb);
        return NULL;
    }

    // Process each version entry
    VersionEntry* entry = version_data;
    while (entry) {
        char key[256];
        snprintf(key, sizeof(key), "version.%s.%s", section_name, entry->name);

        if (!sdb_set(sdb, key, entry->value, 0)) {
            // Failed to insert into Sdb
            free(section_name);
            free_version_definitions(version_data);
            sdb_free(sdb);
            return NULL;
        }

        entry = entry->next;
    }

    free(section_name);
    free_version_definitions(version_data);
    return sdb;
}

