Sdb* process_elf_version_info(ELFOBJ* bin, Elf_Shdr* shdr, int sz) {
    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    if (!shdr || sz <= 0) {
        sdb_free(sdb);
        return NULL;
    }

    // Get section names
    char* section_name = elf_strptr(bin->elf, shdr->sh_link, shdr->sh_name);
    if (!section_name) {
        sdb_free(sdb);
        return NULL;
    }

    // Retrieve version definitions from section data
    Elf_Data* data = elf_getdata(shdr, NULL);
    if (!data || data->d_size == 0) {
        sdb_free(sdb);
        return NULL;
    }

    // Allocate and process each version definition entry
    for (size_t i = 0; i < data->d_size; i += sizeof(Elf_Verdaux)) {
        Elf_Verdaux* entry = (Elf_Verdaux*)((char*)data->d_buf + i);
        char key[256];
        snprintf(key, sizeof(key), "version.%s.%d", section_name, i);

        if (sdb_num_set(sdb, key, entry->vda_name, 0)) {
            continue;
        }

        sdb_free(sdb);
        return NULL;
    }

    return sdb;
}

Sdb* process_elf_version_info(ELFOBJ* bin, Elf_(Shdr)* shdr, int sz) {
    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    // Check section header validity
    if (shdr == NULL || shdr->sh_size == 0 || sz <= 0) {
        sdb_free(sdb);
        return NULL;
    }

    // Calculate the number of entries in the version info section
    size_t num_entries = shdr->sh_size / sz;
    if (shdr->sh_size % sz != 0) {
        sdb_free(sdb);
        return NULL;
    }

    // Allocate memory for version definitions
    char** version_defs = calloc(num_entries, sizeof(char*));
    if (version_defs == NULL) {
        sdb_free(sdb);
        return NULL;
    }

    // Retrieve version information from the binary
    for (size_t i = 0; i < num_entries; ++i) {
        // Assume a helper function elf_get_version_name() that extracts the version name
        // from the binary using the section header and index.
        char* name = elf_get_version_name(bin, shdr, i);
        if (name == NULL) {
            // Clean up and return on error
            for (size_t j = 0; j < i; ++j) {
                free(version_defs[j]);
            }
            free(version_defs);
            sdb_free(sdb);
            return NULL;
        }

        version_defs[i] = name;
        char key[64];
        snprintf(key, sizeof(key), "version.%zu", i);
        sdb_num_put(sdb, key, i);
        sdb_put(sdb, name, "1");
    }

    return sdb;
}
